import sys

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    index = 1
    results = []
    for _ in range(t):
        x = int(input[index])
        index += 1
        if x == 0:
            results.append("1 1")
            continue
        found = False
        for m in range(1, 1000):  # m is reasonably small
            max_ones = 0
            for n in range(m, 10**9 + 1):
                if n % m == 0:
                    max_ones = (n // m - 1) * n + (n % m)
                else:
                    max_ones = (n // m) * n + (n % m)
                if max_ones >= x:
                    if max_ones == x:
                        results.append(f"{n} {m}")
                        found = True
                    break
            if found:
                break
        if not found:
            results.append("-1")
    print("\n".join(results))

if __name__ == "__main__":
    main()
